import os


def files_list(path: str, recursive: bool = False) -> list[str]:
    """List all files in a given directory, including hidden files and directories.

    Args:
        path (str): The path to the directory.
        recursive (bool, optional): Whether to recursively list files in subdirectories. Defaults to False.

    Returns:
        list[str]: A list of filenames in the specified directory.
    """
    if not os.path.exists(path):
        raise FileNotFoundError(f"The specified path '{path}' does not exist.")

    if not os.path.isdir(path):
        return []

    files = []
    for item in os.listdir(path):
        item_path = os.path.join(path, item)
        if os.path.isfile(item_path):
            files.append(item)
        elif os.path.isdir(item_path) and recursive:
            files.extend(files_list(item_path, recursive=True))

    return files


if __name__ == "__main__":
    try:
        print(files_list("/path/to/directory"))
        print(files_list("/path/to/directory", recursive=True))
    except Exception as e:
        print(e)

from typing import List
import zipfile

def files_list_from_zipfile(zip_path: str) -> list[str]:
    """Retrieve a list of file names from a zip archive.

    Args:
        zip_path (str): The path to the zip file.

    Returns:
        list[str]: A list of file names within the zip archive.
    """
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_file:
            return zip_file.namelist()
    except FileNotFoundError:
        raise ValueError(f"The specified zip file path '{zip_path}' does not exist.")
    except zipfile.BadZipFile:
        raise ValueError(f"The file at '{zip_path}' is not a valid zip file.")

if __name__ == "__main__":
    # Example usage
    try:
        print(files_list_from_zipfile("example.zip"))
    except ValueError as e:
        print(e)

