from typing import Callable, Dict

# Dictionary to store the associations between VCS names and methods
vcs_handlers: Dict[str, Callable] = {}

def register_vcs_handler(vcs: str) -> Callable:
    """
    A decorator function that associates a method with a specific version control system (VCS).

    Args:
        vcs (str): The name of the VCS to associate with the method.

    Returns:
        Callable: The decorator function.
    """
    def decorator(method: Callable) -> Callable:
        vcs_handlers[vcs] = method
        return method
    return decorator

# Example usage
@register_vcs_handler('git')
def handle_git():
    print("Handling Git operations")

@register_vcs_handler('svn')
def handle_svn():
    print("Handling SVN operations")

# Function to demonstrate the usage of registered handlers
def run_vcs_handler(vcs: str):
    handler = vcs_handlers.get(vcs)
    if handler:
        handler()
    else:
        print(f"No handler found for {vcs}")

if __name__ == "__main__":
    run_vcs_handler('git')  # Expected output: Handling Git operations
    run_vcs_handler('svn')  # Expected output: Handling SVN operations
    run_vcs_handler('hg')   # Expected output: No handler found for hg

